static void hclge_vf_keep_alive ( struct hclge_vport * vport ) { struct hclge_dev * hdev = vport -> back ; if ( test_bit ( HCLGE_VPORT_STATE_INITED , & vport -> state ) && ! test_bit ( HCLGE_VPORT_STATE_ALIVE , & vport -> state ) ) { set_bit ( HCLGE_VPORT_STATE_ALIVE , & vport -> state ) ; dev_info ( & hdev -> pdev -> dev , "VF %u is alive!" , vport -> vport_id - HCLGE_VF_VPORT_START_NUM ) ; hclge_notify_vf_config ( vport ) ; } } 